<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {useExamStore} from '../stores/exam'
import {useInterviewStore} from '../stores/interview'
import {useVocabularyStore} from '../stores/vocabulary'
import {loadTechnicalGoals} from '../technical-goals-storage'
import type {TechnicalGoal} from '../domain/technical-goals'
import {loadDemo} from '../demo-storage'
import type {DemoPlan} from '../domain/demo-plan-model'
import type {DemoSession} from '../domain/demo'
import {learningDashboard,type DashboardTarget} from '../domain/dashboard'
const emit=defineEmits<{navigate:[target:DashboardTarget];start:[module:'EXAM'|'INTERVIEW'|'VOCABULARY'|'DEMO']}>()
const exam=useExamStore(),interview=useInterviewStore(),vocabulary=useVocabularyStore(),clock=ref(Date.now()),days=ref<7|30>(7),module=ref('ALL')
const plans=ref<DemoPlan[]>([]),demos=ref<DemoSession[]|null>(null),demoReady=ref(false),demoError=ref('')
async function readDemo(){try{const data=await loadDemo();demos.value=data.sessions;plans.value=data.plans}catch{demoError.value='Không đọc được Demo. Không ghi đè khi đọc dashboard.'}finally{demoReady.value=true}}
const goals=ref<TechnicalGoal[]|null>(null),goalsReady=ref(false),goalsError=ref('')
async function readGoals(){try{goals.value=(await loadTechnicalGoals()).goals}catch{goalsError.value='Không đọc được mục tiêu kỹ thuật.'}finally{goalsReady.value=true}}
const timezone=Intl.DateTimeFormat().resolvedOptions().timeZone
const data=computed(()=>learningDashboard({technicalGoals:goals.value,demoPlans:plans.value,demos:demos.value,exams:exam.ready&&!exam.loadFailed?exam.attempts:null,interviews:interview.ready&&!interview.loadFailed?{attempts:interview.attempts,sessions:interview.sessions,queue:interview.reviewQueue}:null,bookmarks:vocabulary.ready&&!vocabulary.loadFailed?vocabulary.bookmarks:null},clock.value,days.value,timezone))
const recent=computed(()=>data.value.recent.filter(a=>module.value==='ALL'||a.module===module.value))
const date=(at:number)=>new Date(at).toLocaleString('vi-VN')
let interval:ReturnType<typeof setInterval>|undefined
onMounted(async()=>{interval=setInterval(()=>{clock.value=Date.now()},1000);await Promise.allSettled([interview.init(),vocabulary.init(),readDemo(),readGoals()])})
onUnmounted(()=>clearInterval(interval))
</script>
<template>
 <div class="learning-dashboard" data-testid="learning-dashboard">
  <div class="eyebrow">GUEST · DỮ LIỆU TRÊN THIẾT BỊ</div><h1 class="page-title">Dashboard học tập</h1><p class="lead">Biết việc đang dở và nơi cần quay lại. Số hoạt động không phải điểm năng lực.</p>
  <p class="notice">Các tổng bên dưới lấy từ trạng thái dữ liệu đang có trong ứng dụng, không phải lịch sử đầy đủ vĩnh viễn. Import/xóa/reset sẽ đổi số liệu. Không cộng điểm Exam, tự đánh giá, AI và mức nhớ thành một điểm chung; không quy đổi JLPT/BJT hoặc tự gán mastery.</p>
  <p v-if="exam.saving||interview.busy||vocabulary.saving" class="notice" role="status">Có thay đổi đang chờ lưu. Giữ trang mở; dashboard có thể đang hiển thị trạng thái mới trong bộ nhớ.</p>
  <p v-if="!exam.ready||!interview.ready||!vocabulary.ready||!demoReady||!goalsReady" class="notice" role="status">Đang đọc từng nhóm dữ liệu; nhóm chưa đọc xong hiển thị N/A.</p>
  <p v-if="exam.loadFailed||interview.loadFailed||vocabulary.loadFailed||demoError||goalsError" class="notice danger" role="alert">Một số nhóm chưa đọc được. N/A không có nghĩa là dữ liệu bằng0; các nhóm còn lại vẫn dùng được. Không ghi đè khi đọc dashboard.</p>
  <div class="dashboard-cards">
   <section class="card form-card" data-testid="dashboard-exam"><h2>Exam Time & Strategy</h2><template v-if="data.exam"><p><strong>{{data.exam.completed}} phiên hoàn tất</strong> · {{data.exam.active}} phiên đang dở · tổng {{data.exam.total}}</p><p>{{data.exam.partsWithInput}} phần có số câu làm/đúng hoặc điểm nhập tay.</p><p class="hint">Không lấy trung bình điểm từ khác đề, cấu hình hoặc nguồn. {{data.exam.missingEndTime}} phiên hoàn tất thiếu mốc kết thúc sẽ không được gán ngày giả trong bảng hoạt động.</p></template><p v-else>N/A · {{exam.loadFailed?'Chưa đọc được Exam':'Chưa đọc xong Exam'}}</p><p v-if="exam.error" class="notice danger">{{exam.error}}</p><div class="actions"><button :disabled="!data.exam" @click="emit('start','EXAM')">Mở Exam</button><button @click="emit('navigate',{kind:'EXAM_DATA'})">Backup Exam</button></div></section>
   <section class="card form-card" data-testid="dashboard-interview"><h2>Interview & role-play</h2><template v-if="data.interview"><p><strong>{{data.interview.reviewed}} attempts đã gửi</strong> · {{data.interview.drafts}} bản nháp · tổng {{data.interview.total}}</p><p>Initial {{data.interview.initial}} · Guided {{data.interview.guided}} · Independent {{data.interview.independent}} (số attempts, chưa là tiến bộ).</p><p>{{data.interview.completeSessions}} / {{data.interview.sessions}} phiên3 lượt hiện hành · {{data.interview.staleSessions}} phiên cần rà soát ngữ cảnh.</p><p class="hint">{{data.interview.selfRatings}} tiêu chí tự chấm có chứng cứ · {{data.interview.aiAssessments}} attempts có AI feedback lưu riêng. “Đã gửi” không có nghĩa đã được đánh giá độc lập.</p></template><p v-else>N/A · {{interview.loadFailed?'Chưa đọc được Interview':'Chưa đọc xong Interview'}}</p><p v-if="interview.error" class="notice danger">{{interview.error}}</p><div class="actions"><button :disabled="!data.interview" @click="emit('start','INTERVIEW')">Mở Interview</button><button @click="emit('navigate',{kind:'INTERVIEW_DATA'})">Backup Interview</button></div></section>
   <section class="card form-card" data-testid="dashboard-queue"><h2>Hàng đợi luyện lại</h2><template v-if="data.interview"><p><strong>{{data.interview.queueOpen}} mục đang mở</strong> · {{data.interview.queueStale}} mục có nguồn đổi (có thể thuộc nhóm mở hoặc đã luyện).</p><p>{{data.interview.queueDone}} mục tự đánh dấu đã luyện; {{data.interview.queueDoneCurrent}} mục còn nguồn/retry hiện hành.</p><p class="hint">Dấu đã luyện là tự khai, không thay điểm và không phải mastery.</p></template><p v-else>N/A · Hàng đợi chưa đọc được từ Interview.</p><button :disabled="!data.interview" @click="emit('navigate',{kind:'QUEUE'})">Xem hàng đợi</button></section>
   <section class="card form-card" data-testid="dashboard-vocabulary"><h2>Từ vựng & lịch ôn</h2><template v-if="data.vocabulary"><p><strong>{{data.vocabulary.due}} thẻ đến hạn</strong> · {{data.vocabulary.waiting}} thẻ chờ · tổng {{data.vocabulary.total}}</p><p>{{data.vocabulary.missingNote}} thẻ thiếu ghi chú · {{data.vocabulary.stale}} thẻ đổi nội dung · {{data.vocabulary.full}} thẻ đạt giới hạn.</p><p class="hint">{{data.vocabulary.ratings}} lượt nhớ tự khai còn trong lịch sử. Reset lịch xóa lượt của từ đó; không dự đoán độ nhớ từ con số này.</p></template><p v-else>N/A · {{vocabulary.loadFailed?'Chưa đọc được Sổ từ':'Chưa đọc xong Sổ từ'}}</p><p v-if="vocabulary.error" class="notice danger">{{vocabulary.error}}</p><div class="actions"><button :disabled="!data.vocabulary" @click="emit('navigate',{kind:'VOCABULARY_REVIEW'})">Mở ôn theo lịch</button><button @click="emit('navigate',{kind:'VOCABULARY_DATA'})">Backup sổ từ</button></div></section>
   <section class="card form-card" data-testid="dashboard-demo"><h2>Project Demo</h2><template v-if="data.demo"><p><strong>{{data.demo.done}} lượt kết thúc timer</strong> · {{data.demo.active}} lượt đang luyện · tổng {{data.demo.total}}</p><p>{{data.demo.ready}} lượt có nội dung và3 trả lời hiện hành · {{data.demo.staleAnswers}} trả lời lỗi thời · {{data.demo.retries}} lượt retry.</p><p>{{data.demo.plansOpen}} kế hoạch mở · {{data.demo.plansDue}} đến ngày · {{data.demo.plansStale}} mục có nguồn đổi · {{data.demo.plansDone}} mục tự ghi nhận đã luyện.</p><p class="hint">{{data.demo.reviews}} mục tự review hiện hành. Không phải điểm kỹ thuật hoặc bằng chứng đã tiến bộ; không lấy ngày tạo làm ngày hoàn tất.</p></template><p v-else>N/A · {{demoError?'Chưa đọc được Demo':'Chưa đọc xong Demo'}}</p><div class="actions"><button :disabled="!data.demo" @click="emit('start','DEMO')">Mở Demo</button><button @click="emit('navigate',{kind:'DEMO_DATA'})">Backup Demo</button></div></section>
   <section class="card form-card" data-testid="dashboard-technical-goals"><h2>Mục tiêu kỹ thuật</h2><template v-if="data.technical"><p><strong>{{data.technical.open}} mục tiêu mở</strong> · {{data.technical.done}} tự ghi nhận đã luyện · tổng {{data.technical.total}}</p><p>{{data.technical.met??'N/A'}} mục mở đủ lượt đúng chế độ · {{data.technical.doneCurrent??'N/A'}} mục đã ghi nhận còn đủ nguồn hiện hành.</p><p>{{data.technical.stale??'N/A'}} liên kết lỗi thời · {{data.technical.missing??'N/A'}} liên kết thiếu.</p><p class="hint">Không phải điểm kỹ năng. N/A khi không đọc được Interview để đối chiếu. Mục tiêu không chứa transcript và cần backup riêng.</p></template><p v-else>N/A · {{goalsError?'Chưa đọc được mục tiêu kỹ thuật':'Chưa đọc xong mục tiêu kỹ thuật'}}</p><button @click="emit('navigate',{kind:'TECHNICAL_GOALS'})">Mở mục tiêu kỹ thuật</button></section>
  </div>
  <section class="card form-card"><h2>Việc có thể làm tiếp</h2><p v-if="!data.actions.length">Chưa có việc dở từ các nhóm đã đọc. Chọn Exam, Interview, Sổ từ hoặc Demo để bắt đầu.</p><article v-for="action in data.actions" :key="action.target.kind" class="mode-box"><h3>{{action.label}}</h3><p>{{action.detail}}</p><button class="primary" @click="emit('navigate',action.target)">Mở việc này</button></article></section>
  <section class="card form-card" data-testid="dashboard-daily"><div class="section-heading"><h2>Hoạt động theo ngày</h2><label>Khoảng ngày hoạt động<select v-model.number="days"><option :value="7">7 ngày</option><option :value="30">30 ngày</option></select></label></div><p class="hint">Ngày theo {{data.timezone}}. Mỗi cột là một loại hoạt động riêng; gửi lại transcript tính thêm một version, không phải thêm một kỹ năng. Ngày không có bản ghi là0 nếu nhóm đã đọc; N/A nếu nhóm chưa đọc.</p><div class="table-wrap"><table><thead><tr><th>Ngày</th><th>Timer Exam kết thúc</th><th>Bản transcript gửi</th><th>Lượt nhớ tự khai</th><th>Lượt Demo tạo mới</th></tr></thead><tbody><tr v-for="row in data.daily" :key="row.day"><th>{{row.day}}</th><td>{{row.exams??'N/A'}}</td><td>{{row.transcripts??'N/A'}}</td><td>{{row.vocabulary??'N/A'}}</td><td>{{row.demoStarts??'N/A'}}</td></tr></tbody></table></div><p v-if="data.omittedTimes" class="hint">{{data.omittedTimes}} hoạt động có timestamp ngoài phạm vi ngày hợp lệ/ở tương lai được bỏ khỏi bảng và danh sách gần đây, không tự đổi ngày.</p></section>
  <section class="card form-card" data-testid="dashboard-recent"><h2>Hoạt động gần đây</h2><label>Lọc hoạt động gần đây<select v-model="module"><option value="ALL">Tất cả nhóm</option><option value="EXAM">Exam</option><option value="INTERVIEW">Interview</option><option value="VOCABULARY">Từ vựng</option><option value="DEMO">Demo</option></select></label><p class="hint">Tối đa20 sự kiện mới nhất còn lưu, không bị giới hạn bởi khoảng ngày ở bảng trên. Không hiển thị transcript, ghi chú, câu trả lời hay URL portfolio trong dashboard.</p><p v-if="!recent.length">Chưa có hoạt động phù hợp.</p><article v-for="event in recent" :key="event.id" class="mode-box"><span class="pill">{{event.module}} · {{date(event.at)}}</span><h3>{{event.label}}</h3><p>{{event.detail}}</p><button @click="emit('navigate',event.target)">Mở dữ liệu hiện tại</button></article></section>
 </div>
</template>
